#include <bits/stdc++.h>
using namespace std;
using ll=long long;
struct DSU{vector<int>p,sz;DSU(int n):p(n),sz(n,1){iota(p.begin(),p.end(),0);}int find(int x){return p[x]==x?x:p[x]=find(p[x]);}void join(int a,int b){a=find(a);b=find(b);if(a!=b){if(sz[a]<sz[b])swap(a,b);p[b]=a;sz[a]+=sz[b];}}};
struct BIT{int n;vector<int>t;BIT(int n=0):n(n),t(n+1){}void add(int x,int v){for(++x;x<=n;x+=x&-x)t[x]+=v;}int sum(int x){int r=0;for(;x>0;x-=x&-x)r+=t[x];return r;}int kth(int k){int p=0;for(int step=1<<20;step;step>>=1)if(p+step<=n&&t[p+step]<k){p+=step;k-=t[p];}return p;}};
ll power(ll a,ll b,ll mod=1000000007){ll r=1;for(;b;b>>=1,a=a*a%mod)if(b&1)r=r*a%mod;return r;}
int main(){string s;int k;cin>>s>>k;int n=s.size();vector<vector<int>>cost(n,vector<int>(n));for(int len=2;len<=n;len++)for(int l=0;l+len<=n;l++){int r=l+len-1;cost[l][r]=(s[l]!=s[r])+(len>2?cost[l+1][r-1]:0);}vector<vector<int>>dp(k+1,vector<int>(n+1,10000)),pre=dp;dp[0][0]=0;for(int p=1;p<=k;p++)for(int r=p;r<=n;r++)for(int l=p-1;l<r;l++)if(dp[p-1][l]+cost[l][r-1]<dp[p][r]){dp[p][r]=dp[p-1][l]+cost[l][r-1];pre[p][r]=l;}int best=1;for(int p=2;p<=k;p++)if(dp[p][n]<dp[best][n])best=p;cout<<dp[best][n]<<'\n';vector<string>parts;for(int p=best,r=n;p;p--){int l=pre[p][r];string t=s.substr(l,r-l);for(int i=0,j=(int)t.size()-1;i<j;i++,j--)t[j]=t[i];parts.push_back(t);r=l;}reverse(parts.begin(),parts.end());for(int i=0;i<(int)parts.size();i++){if(i)cout<<'+';cout<<parts[i];}cout<<'\n';}
